const VALID_CREDENTIALS = { "demo@example.com": "correct-horse" };
const MAX_ATTEMPTS = 3;
const LOCKOUT_SECONDS = 30;

let failedAttempts = 0;
let lockoutTimer = null;
let lockoutRemaining = 0;

function qs(id) {
  return document.getElementById(id);
}

function setStatus(message, isError) {
  const status = qs("status");
  status.textContent = message;
  status.className = isError ? "error" : "success";
}

function startLockout() {
  lockoutRemaining = LOCKOUT_SECONDS;
  const submitBtn = qs("submit-btn");
  submitBtn.disabled = true;

  clearInterval(lockoutTimer);
  lockoutTimer = setInterval(() => {
    lockoutRemaining -= 1;
    if (lockoutRemaining <= 0) {
      clearInterval(lockoutTimer);
      submitBtn.disabled = false;
      failedAttempts = 0;
      setStatus("You can try again now.", false);
      return;
    }
    setStatus(`Too many failed attempts. Try again in ${lockoutRemaining}s.`, true);
  }, 1000);
}

function handleSubmit(e) {
  e.preventDefault();
  const email = qs("email").value.trim();
  const password = qs("password").value;

  if (failedAttempts >= MAX_ATTEMPTS) {
    return;
  }

  if (VALID_CREDENTIALS[email] === password) {
    failedAttempts = 0;
    setStatus("Signed in successfully.", false);
    return;
  }

  failedAttempts += 1;
  const remaining = MAX_ATTEMPTS - failedAttempts;

  if (remaining <= 0) {
    setStatus(`Too many failed attempts. Try again in ${LOCKOUT_SECONDS}s.`, true);
    startLockout();
  } else {
    setStatus(`Incorrect email or password. ${remaining} attempt(s) left before lockout.`, true);
  }
}

function init() {
  qs("login-form").addEventListener("submit", handleSubmit);
}

document.addEventListener("DOMContentLoaded", init);

:root {
  --bg: #f4f6f8;
  --surface: #ffffff;
  --text: #17212b;
  --muted: #5b6875;
  --accent: #0f9d67;
  --border: #dde3e9;
  --error: #c92a2a;
  --radius: 10px;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #101820;
    --surface: #17212b;
    --text: #e8edf2;
    --muted: #8a97a5;
    --accent: #3ddc97;
    --border: #26333f;
    --error: #ff6b6b;
  }
}

* { box-sizing: border-box; }
body { margin: 0; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; background: var(--bg); color: var(--text); }
.wrap { max-width: 420px; margin: 0 auto; padding: 3rem 1.5rem 4rem; }
h1 { margin-bottom: 0.25rem; }
.lede { color: var(--muted); line-height: 1.5; margin-top: 0; }

form { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); padding: 1.5rem; display: flex; flex-direction: column; gap: 1rem; }
.field { display: flex; flex-direction: column; gap: 0.35rem; }
label { font-weight: 600; font-size: 0.9rem; }
input { font: inherit; padding: 0.55rem 0.7rem; border: 1px solid var(--border); border-radius: 6px; background: var(--bg); color: var(--text); }

button { background: var(--accent); color: #05261a; border: none; padding: 0.65rem 1.4rem; border-radius: 6px; font-weight: 700; cursor: pointer; }
button:disabled { opacity: 0.5; cursor: not-allowed; }

.status { font-weight: 600; min-height: 1.2em; }
#status { font-weight: 600; min-height: 1.2em; }
#status.error { color: var(--error); }
#status.success { color: var(--accent); }

.demo-note { color: var(--muted); font-size: 0.85rem; margin-top: 1rem; }
code { background: var(--surface); padding: 0.15rem 0.4rem; border-radius: 4px; }

const { test, expect } = require("@playwright/test");
const path = require("path");

const PAGE_URL = "file://" + path.join(__dirname, "..", "index.html");

test.beforeEach(async ({ page }) => {
  await page.goto(PAGE_URL);
});

test("signs in with valid credentials", async ({ page }) => {
  await page.fill("#email", "demo@example.com");
  await page.fill("#password", "correct-horse");
  await page.click("#submit-btn");

  await expect(page.locator("#status")).toHaveText("Signed in successfully.");
});

test("shows a decreasing attempts warning on wrong credentials", async ({ page }) => {
  await page.fill("#email", "demo@example.com");
  await page.fill("#password", "wrong-password");
  await page.click("#submit-btn");

  await expect(page.locator("#status")).toContainText("2 attempt(s) left");
});

test("locks the form after 3 failed attempts", async ({ page }) => {
  for (let i = 0; i < 3; i++) {
    await page.fill("#email", "demo@example.com");
    await page.fill("#password", "wrong-password");
    await page.click("#submit-btn");
  }

  await expect(page.locator("#submit-btn")).toBeDisabled();
  await expect(page.locator("#status")).toContainText("Too many failed attempts");
});

// Deliberately failing — contributor exercise. The lockout message counts
// down starting from LOCKOUT_SECONDS (30) and only decrements once the
// 1-second interval fires, so it never reads "Try again in 25s" the instant
// lockout triggers on the 3rd attempt. Fix the copy (or fix this test) so it
// passes for the right reason — don't just change the number.
test("lockout message shows 25 seconds remaining immediately", async ({ page }) => {
  for (let i = 0; i < 3; i++) {
    await page.fill("#email", "demo@example.com");
    await page.fill("#password", "wrong-password");
    await page.click("#submit-btn");
  }

  await expect(page.locator("#status")).toContainText("Try again in 25s");
});
